import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"產品介紹","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1793163976000}'),n={name:"zh-TW/guide/introduction.md"};function l(e,a,s,h,g,d){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="產品介紹" tabindex="-1">產品介紹 <a class="header-anchor" href="#產品介紹" aria-label="Permalink to &quot;產品介紹&quot;">​</a></h1><h2 id="關於-nuezip" tabindex="-1">關於 NueZip <a class="header-anchor" href="#關於-nuezip" aria-label="Permalink to &quot;關於 NueZip&quot;">​</a></h2><p>NueZip 是一款專為 macOS 打造的專業壓縮檔管理工具，以速度、可靠性和易用性為設計核心。無論您需要壓縮檔案、解壓縮檔、轉換格式，還是管理受密碼保護的壓縮檔，NueZip 都能以原生 macOS 體驗一手包辦。</p><p>NueZip 使用 Swift 6 與 SwiftUI 打造，充分發揮 Apple Silicon 與 macOS 技術的優勢，提供一款快速、輕量且安全的壓縮檔管理工具。</p><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><h3 id="📦-多格式支援" tabindex="-1">📦 <strong>多格式支援</strong> <a class="header-anchor" href="#📦-多格式支援" aria-label="Permalink to &quot;📦 **多格式支援**&quot;">​</a></h3><p>NueZip 支援所有主流壓縮檔格式：</p><ul><li><strong>RAR</strong> — 唯讀，支援多分割卷</li><li><strong>ZIP</strong> — 通用壓縮，支援 AES 加密</li><li><strong>7-Zip</strong> — 高壓縮比，採用 LZMA2</li><li><strong>TAR</strong> — 封存打包，可搭配選用的 GZIP/BZIP2</li><li><strong>GZIP / BZIP2</strong> — 獨立壓縮格式</li></ul><h3 id="⚡-極速解壓縮" tabindex="-1">⚡ <strong>極速解壓縮</strong> <a class="header-anchor" href="#⚡-極速解壓縮" aria-label="Permalink to &quot;⚡ **極速解壓縮**&quot;">​</a></h3><p>雙引擎架構會針對每種格式選擇最佳後端，確保最快的解壓縮速度。</p><h3 id="🔐-密碼保護與加密" tabindex="-1">🔐 <strong>密碼保護與加密</strong> <a class="header-anchor" href="#🔐-密碼保護與加密" aria-label="Permalink to &quot;🔐 **密碼保護與加密**&quot;">​</a></h3><p>使用業界標準加密建立受密碼保護的壓縮檔。內建的密碼管理員會將憑證安全地儲存在您的本機鑰匙圈中。</p><h3 id="📋-批次操作" tabindex="-1">📋 <strong>批次操作</strong> <a class="header-anchor" href="#📋-批次操作" aria-label="Permalink to &quot;📋 **批次操作**&quot;">​</a></h3><p>一次處理多個檔案：</p><ul><li><strong>批次壓縮</strong> — 將多個項目分別壓縮成個別的壓縮檔</li><li><strong>批次解壓縮</strong> — 同時解壓縮多個壓縮檔</li><li><strong>批次轉換</strong> — 大量轉換壓縮檔之間的格式</li><li><strong>批次加密</strong> — 為多個壓縮檔套用密碼保護</li></ul><h3 id="🛠️-進階工具" tabindex="-1">🛠️ <strong>進階工具</strong> <a class="header-anchor" href="#🛠️-進階工具" aria-label="Permalink to &quot;🛠️ **進階工具**&quot;">​</a></h3><ul><li><strong>壓縮檔修復</strong> — 修復損毀的 RAR 與 ZIP 壓縮檔</li><li><strong>格式轉換</strong> — 在任何受支援的格式之間互相轉換</li><li><strong>效能測試</strong> — 測試壓縮速度與評級</li><li><strong>壓縮檔搜尋</strong> — 依名稱在壓縮檔中尋找檔案</li><li><strong>檔案資訊檢視器</strong> — 檢視壓縮檔項目的詳細中繼資料</li><li><strong>分割卷支援</strong> — 建立多分割卷的壓縮檔</li></ul><h3 id="🖥️-原生-macos-體驗" tabindex="-1">🖥️ <strong>原生 macOS 體驗</strong> <a class="header-anchor" href="#🖥️-原生-macos-體驗" aria-label="Permalink to &quot;🖥️ **原生 macOS 體驗**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — 現代、反應靈敏的介面</li><li><strong>Apple Silicon 原生</strong> — 針對 M 系列晶片優化</li><li><strong>Finder 整合</strong> — 右鍵選單擴充功能</li><li><strong>拖放操作</strong> — 透過選單列拖放面板快速存取</li><li><strong>極低資源占用</strong> — 輕量的背景運作</li></ul><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>作業系統</strong>：macOS 14 Sonoma 或更新版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位元）</li><li><strong>記憶體</strong>：最低 4GB RAM，建議 8GB</li><li><strong>儲存空間</strong>：安裝約需 50 MB</li></ul><h2 id="支援語言" tabindex="-1">支援語言 <a class="header-anchor" href="#支援語言" aria-label="Permalink to &quot;支援語言&quot;">​</a></h2><p>NueZip 支援英文、簡體中文、繁體中文、日文、韓文，以及許多其他語言。</p><h2 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to &quot;開始使用&quot;">​</a></h2><p>如果您是第一次使用 NueZip，請從<a href="/zh-TW/guide/installation.html">安裝指南</a>開始，讓應用程式在您的 Mac 上順利運作。</p>',25)])])}const p=t(n,[["render",l]]);export{c as __pageData,p as default};
